import hashlib
import hmac
import json
import os
import secrets
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import threading

# Configuration
API_SECRET = os.environ.get('MULTI_TENANT_SECRET')
if not API_SECRET:
    raise RuntimeError("MULTI_TENANT_SECRET environment variable required")

# Token validity window in hourly buckets (current bucket + this many prior buckets allowed)
TOKEN_MAX_AGE_BUCKETS = 1

# In-memory store
tenants = {}
documents = {}
lock = threading.Lock()

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def generate_token(tenant_id):
    """Generate HMAC-based auth token for tenant."""
    payload = f"{tenant_id}:{int(time.time()) // 3600}"
    sig = hmac.new(API_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_token(token):
    """Verify token and return tenant_id or None."""
    try:
        parts = token.split(':')
        if len(parts) != 3:
            return None
        tenant_id, timestamp, signature = parts
        expected_payload = f"{tenant_id}:{timestamp}"
        expected_sig = hmac.new(API_SECRET.encode(), expected_payload.encode(), hashlib.sha256).hexdigest()
        if not constant_time_compare(signature, expected_sig):
            return None
        # Enforce token expiration: the embedded hourly bucket must be recent.
        try:
            token_bucket = int(timestamp)
        except (TypeError, ValueError):
            return None
        current_bucket = int(time.time()) // 3600
        # Reject future-dated tokens and tokens older than the allowed window.
        if token_bucket > current_bucket:
            return None
        if current_bucket - token_bucket > TOKEN_MAX_AGE_BUCKETS:
            return None
        return tenant_id
    except Exception:
        return None

def get_tenant_clearance_level(tenant_id):
    """Get the security clearance level for a tenant.
    Returns integer level 1-10, or None if tenant not found."""
    with lock:
        tenant = tenants.get(tenant_id)
        if tenant is None:
            return None
        return tenant.get('clearance_level')

def get_document_required_level(doc_id):
    """Get the minimum clearance level required to access a document.
    Returns integer level 1-10, or None if document not found."""
    with lock:
        doc = documents.get(doc_id)
        if doc is None:
            return None
        return doc.get('required_level')

def check_access_permission(tenant_clearance, doc_required_level):
    """Core authorization check.
    Returns True if tenant has sufficient clearance.

    Security: Uses >= comparison to ensure tenant clearance
    meets or exceeds document requirement.
    """
    try:
        # If either value is missing, deny by default
        if doc_required_level is None:
            return False
        if tenant_clearance is None:
            return False
        # Ensure both are integers before comparison
        if not isinstance(tenant_clearance, int) or not isinstance(doc_required_level, int):
            return False
        # Compare clearance levels
        return tenant_clearance >= doc_required_level
    except (TypeError, ValueError):
        # If comparison fails due to type mismatch, deny access
        return False

def authorize_document_access(tenant_id, doc_id):
    """Full authorization pipeline for document access."""
    tenant_clearance = get_tenant_clearance_level(tenant_id)
    doc_required_level = get_document_required_level(doc_id)

    # Document must exist
    if doc_required_level is None:
        return False, "Document not found"

    # Tenant must have a valid clearance level
    if tenant_clearance is None:
        return False, "Tenant clearance not found"

    # Check permission
    if check_access_permission(tenant_clearance, doc_required_level):
        return True, "Access granted"
    else:
        return False, "Insufficient clearance"

class MultiTenantHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Suppress logs

    def _get_tenant_from_auth(self):
        """Extract and verify tenant from Authorization header."""
        auth = self.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            return None
        token = auth[7:]
        return verify_token(token)

    def _send_json(self, code, data):
        body = json.dumps(data).encode()
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 10240:  # 10KB limit
            self._send_json(413, {"error": "Payload too large"})
            return

        body = self.rfile.read(content_length)
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self._send_json(400, {"error": "Invalid JSON"})
            return

        if path == '/tenant/register':
            self._handle_register(data)
        elif path == '/document/create':
            self._handle_create_doc(data)
        elif path == '/document/access':
            self._handle_access_doc(data)
        else:
            self._send_json(404, {"error": "Not found"})

    def _handle_register(self, data):
        """Register a new tenant with a clearance level."""
        tenant_id = data.get('tenant_id', '')
        clearance = data.get('clearance_level')

        if not tenant_id or not isinstance(tenant_id, str):
            self._send_json(400, {"error": "Invalid tenant_id"})
            return

        if not isinstance(clearance, int) or clearance < 1 or clearance > 10:
            self._send_json(400, {"error": "clearance_level must be int 1-10"})
            return

        with lock:
            tenants[tenant_id] = {'clearance_level': clearance}

        token = generate_token(tenant_id)
        self._send_json(201, {"token": token, "tenant_id": tenant_id})

    def _handle_create_doc(self, data):
        """Create a document with a required clearance level."""
        tenant_id = self._get_tenant_from_auth()
        if not tenant_id:
            self._send_json(401, {"error": "Unauthorized"})
            return

        doc_id = data.get('doc_id', '')
        required_level = data.get('required_level')
        content = data.get('content', '')

        if not doc_id or not isinstance(doc_id, str):
            self._send_json(400, {"error": "Invalid doc_id"})
            return

        if not isinstance(required_level, int) or required_level < 1 or required_level > 10:
            self._send_json(400, {"error": "required_level must be int 1-10"})
            return

        with lock:
            documents[doc_id] = {
                'required_level': required_level,
                'content': str(content)[:4096],
                'owner': tenant_id
            }

        self._send_json(201, {"doc_id": doc_id, "created": True})

    def _handle_access_doc(self, data):
        """Access a document - requires sufficient clearance."""
        tenant_id = self._get_tenant_from_auth()
        if not tenant_id:
            self._send_json(401, {"error": "Unauthorized"})
            return

        doc_id = data.get('doc_id', '')
        if not doc_id or not isinstance(doc_id, str):
            self._send_json(400, {"error": "Invalid doc_id"})
            return

        allowed, reason = authorize_document_access(tenant_id, doc_id)

        if allowed:
            with lock:
                doc = documents.get(doc_id, {})
            self._send_json(200, {
                "doc_id": doc_id,
                "content": doc.get('content', ''),
                "access": "granted",
                "reason": reason
            })
        else:
            self._send_json(403, {"error": reason})

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), MultiTenantHandler)
    server.serve_forever()
